codeExamples.code:
-- Bin-pack compaction across a partition to reach target file size
OPTIMIZE events
WHERE event_date >= '2024-01-01';

-- Compaction plus multi-dimensional clustering for data skipping
OPTIMIZE events
WHERE event_date = '2024-01-15'
ZORDER BY (user_id, event_type);

-- Tune the target file size for this table (default ~1GB)
ALTER TABLE events SET TBLPROPERTIES ('delta.targetFileSize' = '134217728');

-- Enable automatic compaction and optimized writes on ingestion
ALTER TABLE events SET TBLPROPERTIES (
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.autoOptimize.autoCompact' = 'true'
);

-- Reclaim storage from files no longer referenced (respects retention)
VACUUM events RETAIN 168 HOURS;

-- Bin-pack rewrite: merge files smaller than 128MB into ~512MB targets
CALL catalog.system.rewrite_data_files(
  table => 'db.events',
  strategy => 'binpack',
  options => map(
    'target-file-size-bytes', '536870912',
    'min-file-size-bytes', '134217728'
  )
);

-- Sort-based rewrite for better data skipping on filter columns
CALL catalog.system.rewrite_data_files(
  table => 'db.events',
  strategy => 'sort',
  sort_order => 'event_type ASC, user_id ASC',
  where => 'event_date = ''2024-01-15'''
);

-- Compact metadata manifests as well
CALL catalog.system.rewrite_manifests('db.events');

-- Remove snapshots older than retention to delete orphaned files
CALL catalog.system.expire_snapshots(
  table => 'db.events',
  older_than => TIMESTAMP '2024-01-08 00:00:00'
);
